package com.askepedia.entity;

import java.time.Instant;

/**
 * Domain entity representing a row in the 'wiki_passage' database table.
 */
public record Passage(
    Long passageId,
    Long articleId,
    int sequenceNo,
    String passageText,
    Instant createdAt
) {
    /**
     * Convenience factory method for creating a new Passage prior to database insertion
     * (where passageId is auto-generated by the database sequence).
     */
    public static Passage of(Long articleId, int sequenceNo, String passageText) {
        return new Passage(null, articleId, sequenceNo, passageText, Instant.now());
    }
}
